package com.dealhunter.app;
import android.content.*;import android.text.Html;import android.text.Spanned;import android.text.style.URLSpan;import org.json.*;import org.w3c.dom.*;import java.net.URI;import java.util.*;import java.util.regex.*;
final class PriceHistory {
 static String direct(Element e){for(String tag:new String[]{"description","content:encoded"}){NodeList nodes=e.getElementsByTagName(tag);if(nodes.getLength()==0)continue;Spanned s=Html.fromHtml(nodes.item(0).getTextContent(),Html.FROM_HTML_MODE_LEGACY);for(URLSpan span:s.getSpans(0,s.length(),URLSpan.class)){String label=s.subSequence(s.getSpanStart(span),s.getSpanEnd(span)).toString().toLowerCase(Locale.US);if(!label.matches(".*(shop|buy|product|at amazon|at nike|at adidas|at walmart|at target).*"))continue;try{URI u=URI.create(span.getURL());String h=u.getHost();if("https".equals(u.getScheme())&&h!=null&&!h.matches("(?i).*(slickdeals\\.net|dealnews\\.com|reddit\\.com)$"))return u.toString();}catch(Exception ignored){}}}return "";}
 static String key(JSONObject d){return "history:"+d.optString("url");}
 static void record(SharedPreferences p,JSONObject d){try{String title=d.optString("title");Matcher m=Pattern.compile("\\$([0-9]+(?:,[0-9]{3})*(?:\\.[0-9]{2})?)").matcher(title);if(!m.find())return;double price=Double.parseDouble(m.group(1).replace(",",""));if(m.find()||price<=0||title.toLowerCase(Locale.US).matches(".*(from |starting at|up to|under |gift card|cashback|cash back|save \\$).*"))return;JSONArray h=new JSONArray(p.getString(key(d),"[]"));if(h.length()>0&&h.getJSONObject(h.length()-1).getDouble("price")==price)return;h.put(new JSONObject().put("price",price).put("time",System.currentTimeMillis()));p.edit().putString(key(d),h.toString()).apply();}catch(Exception ignored){}}
 static String summary(SharedPreferences p,JSONObject d){try{JSONArray h=new JSONArray(p.getString(key(d),"[]"));if(h.length()==0)return "No unambiguous advertised price recorded yet.";double min=Double.MAX_VALUE;StringBuilder rows=new StringBuilder();for(int i=0;i<h.length();i++){JSONObject v=h.getJSONObject(i);double price=v.getDouble("price");min=Math.min(min,price);rows.append(new java.text.SimpleDateFormat("MMM d, yyyy HH:mm",Locale.US).format(new Date(v.getLong("time")))).append("  ").append(String.format(Locale.US,"$%.2f",price)).append("\n");}return String.format(Locale.US,"Latest observed: $%.2f\nLowest observed: $%.2f\n",h.getJSONObject(h.length()-1).getDouble("price"),min)+(h.length()>1?String.format(Locale.US,"Previous: $%.2f\n",h.getJSONObject(h.length()-2).getDouble("price")):"")+"\n"+rows+"\nAdvertised post prices only; not verified retailer prices. History starts with your scans.";}catch(Exception e){return "History unavailable.";}}
}
